import { axios } from "@pipedream/platform";
import constants from "./common/constants.mjs";
    // ...
export default {
  type: "app",
  app: "serpapi",
  propDefinitions: {
    engine: {
      type: "string",
      label: "Engine",
      description: "Engine to send the query to",
      options: constants.ENGINES,
    },
    q: {
      type: "string",
      label: "Query",
      description: "The query you want to search. You can use anything that you would use in a regular Google search. e.g. `inurl:`, `site:`, `intitle:`. SerpApi also supports advanced search query parameters such as `as_dt` and `as_eq`. See the [full list](https://serpapi.com/advanced-google-query-parameters) of supported advanced search query parameters.",
    },
    device: {
      type: "string",
      label: "Device",
      description: "Defines the device to use to get the results",
      options: constants.DEVICES,
    },
    noCache: {
      type: "boolean",
      label: "No Cache",
      description: "Force SerpApi to fetch the Google results even if a cached version is already present",
    },
  },
  methods: {
    _baseUrl() {
      return "https://serpapi.com";
    },
    async _makeRequest(opts = {}) {
      const {
        $ = this,
        path,
        params,
        ...otherOpts
      } = opts;
      return axios($, {
        ...otherOpts,
        url: this._baseUrl() + path,
        params: {
          ...params,
          api_key: this.$auth.api_key,
        },
      });
    },
    async scrapeSearch(args = {}) {
      return this._makeRequest({
        path: "/search",
        ...args,
      });
    },
  },
};
// ---- file: package/actions/scrape-search/scrape-search.mjs ----
export default {
  key: "serpapi-scrape-search",
  name: "Scrape Search",
  description: "Scrape the results from a search engine via SerpApi service. [See the documentation](https://serpapi.com/search-api)",
  version: "0.0.3",
  type: "action",
  props: {
    app,
    engine: {
      propDefinition: [
        app,
        "engine",
      ],
    },
    q: {
      propDefinition: [
        app,
        "q",
      ],
    },
    device: {
      propDefinition: [
        app,
        "device",
      ],
    },
    noCache: {
      propDefinition: [
        app,
        "noCache",
      ],
    },
  },
  async run({ $ }) {
    const response = await this.app.scrapeSearch({
      $,
      params: {
        engine: this.engine,
      },
      data: {
        q: this.q,
        device: this.device,
        no_cache: Boolean(this.noCache) === true
          ? "true"
          : "false",
      },
    });

    $.export("$summary", `Successfully sent query to '${this.engine}'`);

    return response;
  },
};

